1	/**
2	 * The map: tiles, wires, panning and zooming.
3	 *
4	 * The drawing library owns four things and no more — panning, zooming, working
5	 * out what is under the pointer, and the sockets on the sides of a tile.
6	 * Everything you can see is ours. That is why only the library's bare
7	 * stylesheet is imported below and never its full one: the full one carries the
8	 * library's own look, and a tool that looks like the library it was built with
9	 * looks like a demo. A check in `npm run lint` fails the build if the full one
10	 * ever appears in this tree.
11	 *
12	 * Three things this file works out that no single wire could work out for
13	 * itself, because a wire cannot see where the other tiles are:
14	 *
15	 *   1. **How each wire is routed.** Most arrows join neighbouring columns and
16	 *      take the ordinary route. An arrow that skips a column would run straight
17	 *      through the tile in between and disappear behind it, so it is given a
18	 *      clear corridor to travel along instead; and the one arrow that runs
19	 *      backwards is sent over the top of the map, where there is nothing to
20	 *      cross.
21	 *   2. **The hover lens.** Point at a claim and everything not on its path —
22	 *      neither one of its causes nor one of the things it causes — drops to
23	 *      fifteen per cent.
24	 *   3. **Whether a wire's plate has room for its words.** Below the same zoom at
25	 *      which a tile switches to its summary, a plate's words would land under
26	 *      eleven pixels on the glass, so the plates go. Nothing is scaled down to
27	 *      dodge the rule.
28	 */
29	
30	import {
31	  Background,
32	  BackgroundVariant,
33	  Controls,
34	  ReactFlow,
35	  ReactFlowProvider,
36	  useNodesInitialized,
37	  useReactFlow,
38	  useStore,
39	  useUpdateNodeInternals,
40	} from "@xyflow/react";
41	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
42	import "@xyflow/react/dist/base.css";
43	import { Tile } from "../components/Tile";
44	import { TileOverflow } from "../components/TileOverflow";
45	import type { MapKeys } from "../keyboard/useMapKeys";
46	import { useMapKeys } from "../keyboard/useMapKeys";
47	import type { Selection, WorldView } from "../world";
48	import {
49	  firstFrame,
50	  LARGEST_ZOOM,
51	  SMALLEST_ZOOM,
52	  SUMMARY_BELOW_ZOOM,
53	  TILE_WIDTH,
54	} from "./geometry";
55	import { assignLayers } from "./layers";
56	import { useLayout } from "./layoutRunner";
57	import { mayLandAgain } from "./theKeyboard";
58	import {
59	  type ClaimNode,
60	  type MapEdge,
61	  type MapNode,
62	  OVERFLOW_PREFIX,
63	  type OverflowNode,
64	  toFlow,
65	} from "./toFlow";
66	import { CausalWire } from "./wires/CausalWire";
67	import { onThePathFrom } from "./wires/lens";
68	import { planPlates } from "./wires/plates";
69	import { type Box, planRoutes, SKY_GAP, tailOffsets } from "./wires/route";
70	import { ARROWHEAD, WireMarks } from "./wires/WireMarks";
71	import "./canvas.css";
72	
73	/** The two kinds of box the map draws. Defined once, outside render, so the
74	 * drawing library never has to rebuild its tiles because the object changed. */
75	const TILE_TYPES = {
76	  claim: ({ data }: { data: ClaimNode["data"] }) => (
77	    <Tile
78	      claim={data.claim}
79	      isHypothesis={data.isHypothesis}
80	      versions={data.versions}
81	      height={data.height}
82	    />
83	  ),
84	  overflow: ({ data }: { data: OverflowNode["data"] }) => <TileOverflow count={data.count} />,
85	};
86	
87	/** One kind of wire, ours, saying five things at once. */
88	const WIRE_TYPES = { causal: CausalWire };
89	
90	/** What the map needs beyond the world it draws. */
91	interface SurfaceProps {
92	  /** The world to draw. */
93	  readonly world: WorldView;
94	  /** What the panel beside the map is open on. */
95	  readonly selection: Selection;
96	  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
97	  readonly onSelect: (selection: Selection) => void;
98	  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
99	  readonly focused: string | null;
100	  /** Put the keyboard on a claim. */
101	  readonly onFocused: (id: string | null) => void;
102	  /**
103	   * How tall to draw each tile, when a diff needs one box to hold two paintings.
104	   * Left out, each tile is as tall as its own content.
105	   */
106	  readonly heights?: ReadonlyMap<string, number>;
107	  /**
108	   * Which map this is: the base map, or the base map with one branch folded on.
109	   *
110	   * Both paintings of one diff share it, so flipping between them moves nothing.
111	   * Opening a different branch changes it, and the union of the two worlds is
112	   * then laid out again from scratch — one layout, two paintings.
113	   */
114	  readonly mapKey: string;
115	  /** Everything the keys that are not about moving are wired to. */
116	  readonly keys: MapKeys;
117	  /** Say what the last keystroke did, under the map. */
118	  readonly onStatus: (line: string) => void;
119	  /**
120	   * The reader asked to see the claims a column had no room for.
121	   *
122	   * The collapsed tile does not expand: it opens the outline, filtered to that
123	   * column. The outline is built from the world rather than from what is
124	   * painted, so those claims already have items there and the tile only has to
125	   * point at them.
126	   */
127	  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
128	  /**
129	   * True while the map is arriving, which is when the one animation it spends on
130	   * causality runs: the wires draw in the order the argument runs, a column at a
131	   * time. Under reduced motion the ordering survives and the drawing goes.
132	   */
133	  readonly arriving: boolean;
134	}
135	
136	/**
137	 * Keep asking the drawing library to measure the tiles' handles until it has.
138	 *
139	 * **A wire is drawn between two handles, and a handle's place is measured, not
140	 * declared.** #37 gave the library every tile's own box, because it draws
141	 * nothing it has not measured and a busy browser drops the size notifications
142	 * it measures through. That fixed the tile. It could not fix the wire: where a
143	 * handle sits *inside* a tile is not something a width and a height say, and
144	 * the library learns it from the same dropped notification.
145	 *
146	 * Measured, with every tile's notification dropped and the glass's kept: seven
147	 * tiles drawn, none hidden, twenty-eight handles on the glass — and **not one
148	 * arrow**. A causal map is its arrows; without them it is the wrong picture of
149	 * the argument, and a quiet one, because every claim is still there in its
150	 * place. The end-to-end suite met it about once in a hundred and sixty runs.
151	 *
152	 * `nodesInitialized` is false until every tile has handle bounds, so it is the
153	 * fact to act on rather than a guess about timing, and asking is a direct
154	 * measurement rather than another notification to be dropped. The asking stops
155	 * the moment the library says it has measured.
156	 *
157	 * @param ids Every tile on the glass, by identifier.
158	 */
159	function useHandlesTheLibraryHasMeasured(ids: readonly string[]): void {
160	  const measured = useNodesInitialized();
161	  const measureAgain = useUpdateNodeInternals();
162	  useEffect(() => {
163	    if (measured || ids.length === 0) {
164	      return;
165	    }
166	    // On a timer rather than on an animation frame: a browser produces no
167	    // frames while nothing on the page is changing, and nothing changing is
168	    // precisely the state this is for — #37 learnt that the hard way.
169	    measureAgain([...ids]);
170	    const asking = window.setInterval(() => measureAgain([...ids]), 120);
171	    return () => window.clearInterval(asking);
172	  }, [measured, ids, measureAgain]);
173	}
174	
175	/** The surface itself. Lives inside the provider so it can move the view. */
176	function MapSurface({
177	  world,
178	  selection,
179	  onSelect,
180	  focused,
181	  onFocused,
182	  heights,
183	  mapKey,
184	  keys,
185	  onStatus,
186	  onOverflow,
187	  arriving,
188	}: SurfaceProps) {
189	  const flow = useReactFlow();
190	  const surface = useRef<HTMLDivElement>(null);
191	  const [pointingAt, setPointingAt] = useState<string | null>(null);
192	
193	  const drawing = useMemo(() => toFlow(world, heights), [world, heights]);
194	  // Every tile the glass holds, by identifier — the list the measuring asks
195	  // about, held still so that the asking does not restart on every render.
196	  const everyTile = useMemo(() => drawing.nodes.map((node) => node.id), [drawing.nodes]);
197	  useHandlesTheLibraryHasMeasured(everyTile);
198	  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);
199	
200	  // How far the map is zoomed out. Below the threshold a wire's plate would
201	  // have its words drawn under eleven pixels on the glass, which is the one
202	  // thing nothing in this product is allowed to do, so the plates go and the
203	  // stroke keeps saying what kind of push each wire is.
204	  const zoom = useStore((state) => state.transform[2]);
205	  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;
206	
207	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
208	  const heightOf = useCallback(
209	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
210	    [drawing],
211	  );
212	
213	  /** Where every tile ended up, which is what routing a wire needs to know. */
214	  const boxes = useMemo(() => {
215	    const placed = new Map<string, Box>();
216	    for (const [id, at] of layout.positions) {
217	      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
218	    }
219	    return placed;
220	  }, [layout, heightOf]);
221	
222	  // What the hover lens leaves lit. `null` is everything, which is what the map
223	  // looks like when the reader is not pointing at anything. The claim the
224	  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
225	  // feature.
226	  const lens = useMemo(
227	    () => onThePathFrom(pointingAt ?? focused, world.links),
228	    [pointingAt, focused, world.links],
229	  );
230	
231	  // Which column each claim sits in, for the one animation this map spends on
232	  // causality: the wires arrive in the order the argument runs, a column at a
233	  // time. The order is read from the map's own shape, never from the clock.
234	  const column = useMemo(() => {
235	    const placed = new Map<string, number>();
236	    for (const one of assignLayers(
237	      world.claims.map((claim) => claim.id),
238	      world.links,
239	    )) {
240	      placed.set(one.id, one.layer);
241	    }
242	    return placed;
243	  }, [world]);
244	
245	  const nodes: MapNode[] = useMemo(
246	    () =>
247	      drawing.nodes.map((node) => {
248	        const ghost = node.type === "claim" && node.data.claim.ghost === true;
249	        return {
250	          ...node,
251	          position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
252	          selected: selection?.kind === "claim" && selection.id === node.id,
253	          // Two classes and not one: the hover lens and the other world are both
254	          // opacity, and a tile that is off the hovered path *and* in the other
255	          // world has to land at the two multiplied together rather than at
256	          // whichever rule happened to win. `canvas.css` multiplies them.
257	          className: [
258	            lens !== null && !lens.claims.has(node.id) ? "is-dimmed" : "",
259	            ghost ? "is-ghost" : "",
260	          ]
261	            .filter((one) => one !== "")
262	            .join(" "),
263	        };
264	      }),
265	    [drawing, layout, lens, selection],
266	  );
267	
268	  const edges: MapEdge[] = useMemo(() => {
269	    const routable = drawing.edges.map((edge) => ({
270	      id: edge.id,
271	      source: edge.source,
272	      target: edge.target,
273	      handle: edge.sourceHandle ?? "out-trigger",
274	      reflexive: edge.data?.reflexive === true,
275	      mode: edge.data?.mode ?? "trigger",
276	      strength: edge.data?.strength ?? 0,
277	      lag: edge.data?.lag ?? 0,
278	    }));
279	    const plans = planRoutes(routable, boxes);
280	    const offsets = tailOffsets(routable);
281	    // Where every plate goes, worked out for the whole map at once. A wire
282	    // cannot see its neighbours, and once two worlds are laid over each other
283	    // that is not enough: the union crowds the middle of the map and plates
284	    // began landing on one another.
285	    const plates = planPlates({ wires: routable, boxes, plans, tailOffsets: offsets });
286	    const wires = new Map(world.links.map((link) => [link.id, link]));
287	    return drawing.edges.map((edge) => {
288	      if (edge.data === undefined) {
289	        return edge;
290	      }
291	      const wire = wires.get(edge.id);
292	      return {
293	        ...edge,
294	        selected: selection?.kind === "wire" && selection.id === edge.id,
295	        // The wave's place in the order, and whether this wire belongs to the
296	        // world you are not looking at. Both are carried as classes, because a
297	        // class is what the drawing library puts on the group the wire is drawn
298	        // in, and a wire cannot know where the other wires are.
299	        className: [
300	          `wave-${Math.min(column.get(edge.source) ?? 0, 5)}`,
301	          wire?.ghost === true ? "is-ghost" : "",
302	          wire?.change === undefined ? "" : `is-${wire.change}`,
303	        ]
304	          .filter((one) => one !== "")
305	          .join(" "),
306	        data: {
307	          ...edge.data,
308	          plan: plans.get(edge.id),
309	          tailOffset: offsets.get(edge.id),
310	          plateAt: plates.get(edge.id),
311	          wave: Math.min(column.get(edge.source) ?? 0, 5),
312	          dimmed: lens !== null && !lens.wires.has(edge.id),
313	          tooSmallForWords,
314	        },
315	      };
316	    });
317	  }, [drawing, boxes, lens, selection, tooSmallForWords, world, column]);
318	
319	  /**
320	   * Everything the first frame has to hold: every tile, and the strip of empty
321	   * space above them that the one backwards wire runs along.
322	   */
323	  const mapBounds = useCallback(() => {
324	    const placed = [...layout.positions.entries()];
325	    if (placed.length === 0) {
326	      return null;
327	    }
328	    const left = Math.min(...placed.map(([, at]) => at.x));
329	    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
330	    const top = Math.min(...placed.map(([, at]) => at.y));
331	    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
332	    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
333	    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
334	  }, [drawing, layout, heightOf]);
335	
336	  const framed = useRef<string | null>(null);
337	  const justFramed = useRef(false);
338	  const centredOn = useRef<string | null>(null);
339	
340	  // Frame the map when it is a different map — the first time it is drawn, and
341	  // again when a branch adds a claim to it. Panning, zooming and walking around
342	  // never re-frame: losing your place because the map was rearranged is the most
343	  // disorienting thing a canvas can do.
344	  useEffect(() => {
345	    // Only once the positions really are this map's. Framing from the positions
346	    // worked out for the map before the branch would frame the wrong thing, and
347	    // the right thing would then arrive underneath it.
348	    if (layout.runs === 0 || layout.laidOutFor !== mapKey || framed.current === mapKey) {
349	      return;
350	    }
351	    const frame = mapBounds();
352	    const room = surface.current?.getBoundingClientRect();
353	    if (frame === null || room === undefined) {
354	      return;
355	    }
356	    // Framed to fit — but never zoomed out past the point where a full tile would
357	    // have to become a summary. The reader's first sight of the map is tiles they
358	    // can read; if the whole map does not fit at that size, it is framed from its
359	    // beginning, on the left, where the map starts, and they pan to the rest.
360	    flow.setViewport(firstFrame(frame, { width: room.width, height: room.height }), {
361	      duration: 0,
362	    });
363	    framed.current = mapKey;
364	    justFramed.current = true;
365	  }, [layout.runs, layout.laidOutFor, flow, mapBounds, mapKey]);
366	
367	  // The view follows whatever the keyboard is on, so a step along a wire never
368	  // walks off the edge of the glass. It does not fight the framing above: when a
369	  // branch has just arrived and moved focus to the claim it added, the whole map
370	  // has already been framed and that claim is in it.
371	  useEffect(() => {
372	    if (focused === null || layout.runs === 0 || centredOn.current === focused) {
373	      // Only when the keyboard has actually moved. Flipping between the two
374	      // worlds redraws every tile and moves none of them, and a view that slid
375	      // sideways on the flip would make the reader hunt for what changed — which
376	      // is the one thing the flip exists to show.
377	      return;
378	    }
379	    if (justFramed.current) {
380	      justFramed.current = false;
381	      centredOn.current = focused;
382	      return;
383	    }
384	    const node = flow.getNode(focused);
385	    if (node === undefined) {
386	      return;
387	    }
388	    centredOn.current = focused;
389	    flow.setCenter(node.position.x + TILE_WIDTH / 2, node.position.y + heightOf(focused) / 2, {
390	      zoom: flow.getZoom(),
391	      duration: 0,
392	    });
393	  }, [focused, flow, heightOf, layout.runs]);
394	
395	  /** Show the claims a column had no room for, as a list. */
396	  const openColumn = useCallback(
397	    (layer: number) => {
398	      onOverflow({
399	        layer,
400	        claims: [...column.entries()].filter(([, at]) => at === layer).map(([id]) => id),
401	      });
402	      onStatus(`the claims in column ${layer}, as a list`);
403	    },
404	    [column, onOverflow, onStatus],
405	  );
406	
407	  /**
408	   * What the reader just pointed at, or `null` when it was the empty map.
409	   *
410	   * Read off the page rather than from the drawing library, deliberately. The
411	   * library reports a click on a tile only through the machinery that also drags
412	   * tiles around, and tiles here do not drag — so that report never arrives.
413	   * Asking the page what was under the pointer is one line, and it gives the
414	   * same answer for a wire, a tile and the empty map.
415	   */
416	  const whatIsUnder = useCallback((target: HTMLElement | null): Selection => {
417	    const wire = target?.closest<HTMLElement>(".react-flow__edge");
418	    if (wire?.dataset.id !== undefined) {
419	      return { kind: "wire", id: wire.dataset.id };
420	    }
421	    const tile = target?.closest<HTMLElement>(".react-flow__node");
422	    if (tile?.dataset.id !== undefined) {
423	      return { kind: "claim", id: tile.dataset.id };
424	    }
425	    return null;
426	  }, []);
427	
428	  /**
429	   * Find a tile or a wire on the glass by the identifier it carries.
430	   *
431	   * By reading each element's own identifier rather than by asking the page for
432	   * a match: a wire is named after its two ends — `H->B` — and the arrow in the
433	   * middle of that is not a character an address for an element may contain.
434	   */
435	  const onTheGlass = useCallback((kind: "node" | "edge", id: string): HTMLElement | undefined => {
436	    const all = surface.current?.querySelectorAll<HTMLElement>(`.react-flow__${kind}`) ?? [];
437	    return [...all].find((one) => one.dataset.id === id);
438	  }, []);
439	
440	  /** Which claim the keyboard is standing on right now, read off the glass. */
441	  const standingOn = useCallback(
442	    (): string | undefined =>
443	      document.activeElement?.closest<HTMLElement>(".react-flow__node")?.dataset.id,
444	    [],
445	  );
446	
447	  /** The tile the keyboard was last asked to stand on, so a late move can be dropped. */
448	  const wantedTile = useRef<string | null>(null);
449	
450	  /**
451	   * Put the keyboard on a tile, and make it stick.
452	   *
453	   * **A tile that is being rebuilt cannot be focused.** The drawing library
454	   * rebuilds a tile's element when what it knows about it changes — which
455	   * selecting one does — so the element found on the glass this instant is
456	   * sometimes the one about to be thrown away, and focusing it does nothing at
457	   * all. The keyboard then stays on the tile it was on while the ring, the
458	   * panel and the line under the map all move to the new one: the page says the
459	   * reader is on the hypothesis and the next keystroke walks from Brent.
460	   *
461	   * The same hazard is already handled for wires below, in the same way. Here
462	   * the move is made at once, and made again after the rebuild has been and
463	   * gone if it did not take — and only if it is still the move the reader last
464	   * asked for, so that two quick steps do not drag the keyboard back to the
465	   * first one.
466	   *
467	   * **And only from nowhere.** The second landing waits on animation frames,
468	   * and frames are not a clock: a browser produces none while nothing on the
469	   * page is changing, so it can run long after it was scheduled — and the frame
470	   * that finally runs it is very often one the reader caused by doing something
471	   * else. `theKeyboard.ts` has the rule and the reason.
472	   */
473	  const putTheKeyboardOn = useCallback(
474	    (id: string): void => {
475	      wantedTile.current = id;
476	      const land = (): void => onTheGlass("node", id)?.focus({ preventScroll: true });
477	      land();
478	      requestAnimationFrame(() => {
479	        requestAnimationFrame(() => {
480	          if (
481	            !mayLandAgain({
482	              wanted: wantedTile.current,
483	              forTile: id,
484	              standingOn: standingOn(),
485	              active: document.activeElement,
486	              surface: surface.current,
487	            })
488	          ) {
489	            return;
490	          }
491	          land();
492	        });
493	      });
494	    },
495	    [onTheGlass, standingOn],
496	  );
497	
498	  /**
499	   * Fill the panel with whatever was pressed, or empty it on a press on the map.
500	   *
501	   * It listens for the press rather than the click, and that is not a detail:
502	   * the drawing library grabs the pointer on the surface the moment a press
503	   * begins, so that dragging the map keeps working when the pointer wanders off
504	   * a tile — and from then on every event, the click included, is reported
505	   * against the surface rather than against what was actually under the pointer.
506	   * The press is the last moment the page can still say what was pressed.
507	   */
508	  const onPointAt = useCallback(
509	    (event: React.PointerEvent<HTMLDivElement>) => {
510	      const under = whatIsUnder(event.target as HTMLElement);
511	      // The zoom buttons and the library's own furniture are not the map.
512	      if (under === null && (event.target as HTMLElement).closest(".react-flow__controls")) {
513	        return;
514	      }
515	      if (under?.kind === "claim" && under.id.startsWith(OVERFLOW_PREFIX)) {
516	        openColumn(Number(under.id.slice(OVERFLOW_PREFIX.length)));
517	        return;
518	      }
519	      onSelect(under);
520	      if (under?.kind === "claim") {
521	        onFocused(under.id);
522	        // Pointing at a tile and reaching it with the keyboard land in the same
523	        // place, so the ring says where you are whichever way you got there —
524	        // and the pointer's landing is made to stick for the same reason the
525	        // keyboard's is.
526	        putTheKeyboardOn(under.id);
527	      }
528	    },
529	    [onSelect, whatIsUnder, onFocused, openColumn, putTheKeyboardOn],
530	  );
531	
532	  /**
533	   * Remember what the reader is on, fill the panel with it, and bring it into
534	   * view if it is off the edge of the screen.
535	   *
536	   * This catches the keyboard as well as the pointer. Reaching a claim or an
537	   * arrow with the keyboard and reaching it with the pointer do the same thing:
538	   * the panel beside the map reads it out. Nothing opens over the map, and
539	   * there is nothing to dismiss.
540	   */
541	  const onFocus = useCallback(
542	    (event: React.FocusEvent<HTMLDivElement>) => {
543	      const target = event.target as HTMLElement;
544	      const under = whatIsUnder(target);
545	      if (under === null) {
546	        return;
547	      }
548	      if (under.kind === "wire") {
549	        // **Landing on a wire does not select it, and that is not an
550	        // oversight.** The drawing library rebuilds a wire's element when it
551	        // becomes selected, and rebuilding the element the keyboard is standing
552	        // on drops focus to the page — which made tabbing through the map
553	        // impossible, because the wires come before the tiles. So a wire fills
554	        // the panel when you press Enter on it, and the focus is put back on the
555	        // rebuilt wire straight afterwards, which is what the effect below is
556	        // for. Pointing at one with the mouse is unchanged.
557	        return;
558	      }
559	      onSelect(under);
560	      onFocused(under.id);
561	    },
562	    [onSelect, whatIsUnder, onFocused],
563	  );
564	
565	  // Where every tile ended up, in the shape moving along a wire needs: the
566	  // keyboard asks what it can *walk to*, which reads the whole map, feedback
567	  // arrows included.
568	  const places = useMemo(() => {
569	    const map = new Map<string, { x: number; y: number; height: number }>();
570	    for (const [id, at] of layout.positions) {
571	      map.set(id, { x: at.x, y: at.y, height: heightOf(id) });
572	    }
573	    return map;
574	  }, [layout, heightOf]);
575	
576	  const claimWords = useCallback(
577	    (id: string) => world.claims.find((claim) => claim.id === id)?.claim ?? id,
578	    [world],
579	  );
580	
581	  const onKeyDown = useMapKeys({
582	    wires: world.links,
583	    positions: places,
584	    focused,
585	    onFocused: (id) => {
586	      onFocused(id);
587	      // Reaching a tile with the keyboard and reaching it with the pointer do
588	      // the same thing: the panel beside the map reads it out. Nothing opens
589	      // over the map.
590	      onSelect({ kind: "claim", id });
591	      putTheKeyboardOn(id);
592	    },
593	    onStatus,
594	    keys,
595	    words: claimWords,
596	  });
597	
598	  // A wire the reader has just asked for, so that focus can be put back on it
599	  // once the drawing library has rebuilt it.
600	  const askedForWire = useRef<string | null>(null);
601	
602	  // biome-ignore lint/correctness/useExhaustiveDependencies: the selection is not read inside — it is what this is waiting for. The wire is rebuilt because the selection changed, so the selection is exactly the right thing to hang this on.
603	  useEffect(() => {
604	    const id = askedForWire.current;
605	    if (id === null) {
606	      return;
607	    }
608	    askedForWire.current = null;
609	    // Two frames, not none. The drawing library keeps its own record of what is
610	    // selected and rebuilds the wire's element from it a frame later, so putting
611	    // focus back on the element that is there right now would put it on the one
612	    // about to be thrown away.
613	    //
614	    // And the same rule as a tile's landing: two frames later can be much later,
615	    // because a browser produces no frames while nothing changes — so this takes
616	    // the keyboard back from nowhere and never from somewhere.
617	    const frame = requestAnimationFrame(() => {
618	      requestAnimationFrame(() => {
619	        if (
620	          !mayLandAgain({
621	            wanted: id,
622	            forTile: id,
623	            standingOn: undefined,
624	            active: document.activeElement,
625	            surface: surface.current,
626	          })
627	        ) {
628	          return;
629	        }
630	        onTheGlass("edge", id)?.focus();
631	      });
632	    });
633	    return () => cancelAnimationFrame(frame);
634	  }, [selection, onTheGlass]);
635	
636	  // The keyboard map, bound once on the page. On the page rather than on the map
637	  // itself, because a key bound to the element you happen to be standing on is a
638	  // key that stops working the moment you press Tab — and every key below is left
639	  // alone while the keyboard is in a field.
640	  useEffect(() => {
641	    const onKey = (event: KeyboardEvent): void => {
642	      // A collapsed tile is reached with the keyboard like any other, and Enter
643	      // opens what is behind it — the same thing a press does.
644	      const target = event.target as HTMLElement | null;
645	      const at = target?.closest<HTMLElement>(".react-flow__node");
646	      if (event.key === "Enter" && at?.dataset.id?.startsWith(OVERFLOW_PREFIX) === true) {
647	        event.preventDefault();
648	        openColumn(Number(at.dataset.id.slice(OVERFLOW_PREFIX.length)));
649	        return;
650	      }
651	      // Enter on a wire reads it out in the panel beside the map — the same
652	      // thing pointing at it does. It is Enter rather than merely landing on it
653	      // because of what the comment above `onFocus` explains.
654	      const wire = target?.closest<HTMLElement>(".react-flow__edge");
655	      if ((event.key === "Enter" || event.key === " ") && wire?.dataset.id !== undefined) {
656	        event.preventDefault();
657	        askedForWire.current = wire.dataset.id;
658	        onSelect({ kind: "wire", id: wire.dataset.id });
659	        onStatus(`this arrow, read out in the panel beside the map`);
660	        return;
661	      }
662	      onKeyDown(event);
663	    };
664	    window.addEventListener("keydown", onKey);
665	    return () => window.removeEventListener("keydown", onKey);
666	  }, [onKeyDown, openColumn, onSelect, onStatus]);
667	
668	  return (
669	    <div
670	      className="canvas"
671	      ref={surface}
672	      data-arriving={arriving ? "yes" : "no"}
673	      onFocusCapture={onFocus}
674	      onPointerDownCapture={onPointAt}
675	    >
676	      <WireMarks />
677	
678	      <ReactFlow
679	        nodes={nodes}
680	        edges={edges}
681	        nodeTypes={TILE_TYPES}
682	        edgeTypes={WIRE_TYPES}
683	        // Tiles do not move. Automatic layout decides where a claim sits, and a
684	        // tile you can drag half of the time — snapping back whenever the map is
685	        // laid out again — reads as broken. Pinning, grouping and annotating
686	        // arrive later as things you ask for, not as free dragging.
687	        nodesDraggable={false}
688	        nodesConnectable={false}
689	        // A tile and a wire both answer to the pointer and to the keyboard. A
690	        // wire has to: everything it says on the glass it says again in words in
691	        // the panel, and the only way to ask for those words is to reach it.
692	        elementsSelectable={true}
693	        nodesFocusable={true}
694	        edgesFocusable={true}
695	        // Selecting a wire must not lift it above the others. The drawing
696	        // library's default is to re-sort the wires when one is selected so the
697	        // selected one draws on top — and re-sorting them moves the element the
698	        // keyboard is standing on, which drops focus to the page and makes
699	        // tabbing through the map impossible. Nothing here needs the lift: a
700	        // selected wire is marked by a ring, and how wires cross is settled by
701	        // routing rather than by drawing order.
702	        elevateNodesOnSelect={false}
703	        onNodeMouseEnter={(_, node) => setPointingAt(node.id)}
704	        onNodeMouseLeave={() => setPointingAt(null)}
705	        // As far out as the map goes, and no further: past this the summary
706	        // tile's words would be drawn smaller than anything in this product is
707	        // allowed to be.
708	        minZoom={SMALLEST_ZOOM}
709	        maxZoom={LARGEST_ZOOM}
710	        proOptions={{ hideAttribution: false }}
711	        // Named, not addressed: the drawing library writes the address around
712	        // the name itself.
713	        defaultEdgeOptions={{ markerEnd: ARROWHEAD }}
714	      >
715	        <Background variant={BackgroundVariant.Dots} gap={32} size={1} />
716	        <Controls showInteractive={false} position="bottom-left" />
717	      </ReactFlow>
718	
719	      {layout.failure === null ? null : (
720	        <p className="canvas__failure">{`The map could not be laid out. ${layout.failure}`}</p>
721	      )}
722	    </div>
723	  );
724	}
725	
726	/** What the map needs to be dropped into a page. */
727	export type MapCanvasProps = SurfaceProps;
728	
729	/** The map, ready to be dropped into a page. */
730	export function MapCanvas(props: MapCanvasProps) {
731	  return (
732	    <ReactFlowProvider>
733	      <MapSurface {...props} />
734	    </ReactFlowProvider>
735	  );
736	}
