/* ---- The sockets -------------------------------------------------------- *
 * One group of inputs on the left, one group of outputs on the right, and two
 * sockets in each: an arrow that fires once and stays fired lands in a
 * different socket from one that has to keep holding. A single tick for the
 * first, a double tick for the second — the same doubling the wire itself will
 * use, so the socket and the wire say the same thing.
 *
 * These override the drawing library's own handle styling, which is a blue
 * circle. Nothing in this product looks like the library it was built with. */

.tile__port.react-flow__handle {
  width: var(--space-2);
  height: 6px;
  min-width: 0;
  min-height: 0;
  border: none;
  border-radius: 0;
  background: none;
  transform: translate(0, -50%);
}

.tile__port.react-flow__handle.react-flow__handle-left {
  left: -8px;
}

.tile__port.react-flow__handle.react-flow__handle-right {
  right: -8px;
}

/* One bar: fires once, and stays fired. */
.tile__port--trigger {
  background: linear-gradient(var(--text-muted) 0 2px, transparent 2px 6px);
  background-position: 0 2px;
}

